'use client';
import { useEffect, useState } from 'react';
import Link from 'next/link';
import { ArrowLeft, ArrowRight, ArrowUpRight, Check, CheckCircle2, Clock3, Printer, BookOpen, FlaskConical, NotebookPen, Scale, List, Download, CloudCheck } from 'lucide-react';
import type { Topic } from '@/lib/types';
import { units, labs } from '@/lib/course';
import { topics } from '@/data';
import { lawMap } from '@/data/laws';
import { useWorkspace } from './WorkspaceProvider';
import { BookmarkButton, UnitIcon, SourceList, InfoNote } from './ui';
import { LessonBody, FieldExercise } from './LessonContent';
import QuizCard from './QuizCard';

export default function LessonReader({ topic }: { topic: Topic }) {
  const { state, ready, saving, error, toggleComplete, visitTopic, update, recordAttempt } = useWorkspace(); const [tab, setTab] = useState('lesson');
  const unit = units[topic.unit - 1]; const index = topics.findIndex(t => t.id === topic.id); const prev = topics[index - 1], next = topics[index + 1]; const lab = labs.find(l => l.id === topic.labId); const complete = state.completed.includes(topic.id); const note = state.notes[topic.id] || '';
  useEffect(() => { if (ready) visitTopic(topic.id); }, [topic.id, ready, visitTopic]);
  const exportNotes = () => { const blob = new Blob([`TRACE · Lesson ${topic.id}\n${topic.title}\n\n${note}`], { type: 'text/plain' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `trace-notes-${topic.id}.txt`; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); };
  return <div key={topic.id} className="page-enter lesson-page"><Link className="back-link" href="/curriculum"><ArrowLeft size={14} />Back to curriculum</Link><div className="lesson-header"><div className="lesson-header-meta"><span className={`tag unit-tag ${unit.color}`}><UnitIcon name={unit.icon} size={13} />UNIT {unit.roman} · LESSON {topic.id}</span><span><Clock3 size={13} />{topic.minutes} min read</span></div><h1>{topic.title}</h1><p>{topic.summary}</p><div className="lesson-header-actions"><button className={`button ${complete ? 'button-completed' : 'button-primary'}`} onClick={() => toggleComplete(topic.id)} disabled={!ready}>{complete ? <CheckCircle2 size={16} /> : <Check size={16} />}{complete ? 'Lesson completed' : 'Mark as complete'}</button><BookmarkButton id={`topic:${topic.id}`} label /><Link href={`/print?topic=${topic.id}`} className="button button-secondary"><Printer size={16} />Print / PDF</Link></div></div>
    <div className="lesson-layout"><div><div className="tabs" role="tablist" aria-label="Lesson sections">{[['lesson', 'The lesson', BookOpen], ['exercise', 'Field exercise', FlaskConical], ['notes', 'My notes', NotebookPen], ['sources', 'Sources', Scale]].map(([id, label, Icon]) => { const TabIcon = Icon as typeof BookOpen; return <button role="tab" aria-selected={tab === id} className={tab === id ? 'active' : ''} key={id as string} onClick={() => setTab(id as string)}><TabIcon size={15} />{label as string}{id === 'notes' && note && <span className="note-dot" />}</button>; })}</div>
    {tab === 'lesson' && <><LessonBody topic={topic} /><div className="lesson-takeaway"><span><CheckCircle2 size={21} /></span><div><h3>The idea to take with you</h3><p>{topic.practice.debrief}</p></div></div><QuizCard question={topic.question} onAnswer={(correct, selected) => recordAttempt({ id: crypto.randomUUID(), date: new Date().toISOString(), score: correct ? 1 : 0, total: 1, mode: `Lesson ${topic.id}`, answers: { [topic.question.id]: selected } })} /><div className="lesson-next-step"><div><FlaskConical size={23} /><section><h3>Turn understanding into a skill.</h3><p>Try “{topic.practice.title}” in the field exercise.</p></section></div><button className="button button-secondary" onClick={() => { setTab('exercise'); window.scrollTo({ top: 220, behavior: 'smooth' }); }}>Try the exercise<ArrowRight size={15} /></button></div></>}
    {tab === 'exercise' && <><FieldExercise topic={topic} />{lab && <Link href={`/labs/${lab.id}`} className="connected-lab"><FlaskConical size={27} /><div><span className="eyebrow">CONTINUE IN THE LAB</span><h3>{lab.title}</h3><p>{lab.subtitle}</p></div><ArrowUpRight size={22} /></Link>}<div className="panel reflection-panel"><h3>Before you move on</h3><p>Explain your reasoning in your own words. What evidence would change your conclusion?</p><button className="button button-secondary" onClick={() => setTab('notes')}><NotebookPen size={15} />Write a reflection</button></div></>}
    {tab === 'notes' && <div className="panel notes-editor"><div className="section-heading"><h2>Your thinking, in your own words.</h2><NotebookPen size={21} /></div><p className="section-subtitle">Private to this browser’s learning workspace. Notes are included in your print export.</p><label htmlFor="lesson-note" className="field-label">Notes for {topic.id} · {topic.title}</label><textarea id="lesson-note" placeholder="What clicked? What would you investigate next?\n\nTry: key idea → evidence → limitation → next step." value={note} maxLength={12000} disabled={!ready} onChange={e => update({ notes: { ...state.notes, [topic.id]: e.target.value } })} /><div className="notes-footer"><span>{note.trim() ? note.trim().split(/\s+/).length : 0} words <i />{saving ? 'Saving…' : state.notes[topic.id] && error ? 'Not yet saved — retry above' : 'Saved to your workspace'}</span><button className="text-link" disabled={!note} onClick={exportNotes}><Download size={14} />Download .txt</button></div><InfoNote>Use your own words, not personal or confidential case information. This is a classroom workspace.</InfoNote></div>}
    {tab === 'sources' && <><div className="panel"><h2>Trace the idea to its source.</h2><p className="section-subtitle">Primary texts, official guidance, and judgment reproductions. Follow the links to read the original material.</p><SourceList ids={topic.sources} /></div><InfoNote warning>Educational explanations are not legal advice. Check amendments, commencement, and the law applicable to the incident date.</InfoNote></>}
    <div className="lesson-pagination">{prev ? <Link href={`/topics/${prev.id}`}><ArrowLeft size={18} /><div><small>PREVIOUS LESSON · {prev.id}</small><strong>{prev.title}</strong></div></Link> : <Link href="/curriculum"><ArrowLeft size={18} /><div><small>THE COMPLETE COURSE</small><strong>Back to your curriculum</strong></div></Link>}{next && <Link href={`/topics/${next.id}`} className="next"><div><small>NEXT LESSON · {next.id}</small><strong>{next.title}</strong></div><ArrowRight size={18} /></Link>}</div></div>
    <aside className="lesson-aside"><div className="lesson-outline"><h3><List size={16} />In this lesson</h3>{topic.sections.map((s, i) => <button key={s.title} onClick={() => { setTab('lesson'); setTimeout(() => document.getElementById(`section-${i + 1}`)?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 30); }}><span>{String(i + 1).padStart(2, '0')}</span>{s.title}</button>)}<div className="outline-divider" /><span className="outline-extra"><FlaskConical size={14} />Practical exercise</span><span className="outline-extra"><CheckCircle2 size={14} />Knowledge check</span></div><div className="objectives-card"><span className="eyebrow">BY THE END, YOU CAN</span>{topic.objectives.map(o => <p key={o}><Check size={14} />{o}</p>)}</div>{lab && <Link href={`/labs/${lab.id}`} className="aside-lab"><FlaskConical size={24} /><span className="eyebrow">LEARN BY DOING</span><h3>{lab.title}</h3><span className="text-link">Open simulation<ArrowUpRight size={14} /></span></Link>}<div className="related-laws"><h3><Scale size={16} />The legal connections</h3>{topic.lawIds.map(id => { const law = lawMap[id]; return law ? <Link key={id} href={`/laws/${id}`}><span>{law.short}</span><ArrowUpRight size={13} /></Link> : null; })}</div></aside></div>
  </div>;
}
