'use client';
import { useState } from 'react';
import { CheckCircle2, XCircle, ArrowRight, RotateCcw, Lightbulb } from 'lucide-react';
import type { Question } from '@/lib/types';
export default function QuizCard({ question, onAnswer, compact = false }: { question: Question; onAnswer?: (correct: boolean, selected: number) => void; compact?: boolean }) {
  const [selected, setSelected] = useState<number | null>(null); const [checked, setChecked] = useState(false);
  const correct = selected === question.answer;
  return <div className={`quiz-card ${compact ? 'compact' : ''}`}><div className="quiz-eyebrow"><Lightbulb size={16} /><span>A MOMENT TO THINK</span></div><h3>{question.prompt}</h3><div className="quiz-options" role="radiogroup" aria-label={question.prompt}>{question.options.map((option, i) => <button key={option} role="radio" aria-checked={selected === i} disabled={checked} onClick={() => setSelected(i)} className={`quiz-option ${selected === i ? 'selected' : ''} ${checked && i === question.answer ? 'correct' : ''} ${checked && selected === i && !correct ? 'incorrect' : ''}`}><span className="option-letter">{String.fromCharCode(65 + i)}</span><span>{option}</span>{checked && i === question.answer && <CheckCircle2 size={17} />}{checked && selected === i && !correct && <XCircle size={17} />}</button>)}</div>{checked ? <><div className={`quiz-feedback ${correct ? 'correct' : 'incorrect'}`} role="status">{correct ? <CheckCircle2 size={19} /> : <Lightbulb size={19} />}<div><strong>{correct ? 'That’s a sound connection.' : 'A useful opportunity to revisit.'}</strong><p>{question.explanation}</p></div></div><button className="text-link quiz-retry" onClick={() => { setChecked(false); setSelected(null); }}><RotateCcw size={14} />Try again</button></> : <button className="button button-primary" disabled={selected === null} onClick={() => { if (selected === null) return; setChecked(true); onAnswer?.(correct, selected!); }}>Check my understanding<ArrowRight size={15} /></button>}</div>;
}
